def truncate_words(text, limit):
    """
    Returns the first 'limit' whitespace-separated tokens of the input text.

    Args:
        text (str): The input text to process
        limit (int): The maximum number of words to return

    Returns:
        str: First 'limit' words joined by single spaces, or empty string if limit <= 0
    """
    # Handle edge cases
    if not isinstance(text, str):
        return ""

    if limit <= 0:
        return ""

    # Split into words and take first 'limit' words
    words = text.strip().split()
    if len(words) <= limit:
        return " ".join(words)
    else:
        return " ".join(words[:limit])
